@code {
    private int _step = 1;
    private Order _order = new();

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private void GoToPayment()
    {
        _step = 2;
    }

    private void GoBackToShipping()
    {
        _step = 1;
    }

    private async Task PlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@if (_step == 1)
{
    <ShippingStep Shipping="_order.Shipping" OnNext="GoToPayment" />
}
else
{
    <PaymentStep Payment="_order.Payment"
                 OnBack="GoBackToShipping"
                 OnPlaceOrder="PlaceOrder" />
}

@implements IDisposable
@inject IAddressValidator AddressValidator

<div class="shipping-step">
    <h3>Shipping Information</h3>

    <label>
        Name
        <input @bind="Shipping.Name" @bind:event="oninput" />
    </label>

    <label>
        Address
        <input @bind="Shipping.Address" @bind:event="oninput" />
    </label>

    <label>
        City
        <input @bind="Shipping.City" @bind:event="oninput" />
    </label>

    <label>
        Zip Code
        <input @bind="Shipping.ZipCode" @bind:event="oninput" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error">@_errorMessage</div>
    }

    <button disabled="@_isValidating" @onclick="ValidateAndProceed">
        @if (_isValidating)
        {
            <span class="spinner" aria-hidden="true"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _errorMessage;

    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private async Task ValidateAndProceed()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(Shipping.Name) ||
            string.IsNullOrWhiteSpace(Shipping.Address) ||
            string.IsNullOrWhiteSpace(Shipping.City) ||
            string.IsNullOrWhiteSpace(Shipping.ZipCode))
        {
            _errorMessage = "All fields are required.";
            return;
        }

        // Cancel any in-flight validation before starting a new one.
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was superseded or the component is being disposed — nothing to do.
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

